131	\begin{lemma}[Axis-line polynomial agreement bound]\label{lem:axis-line-polynomial-agreement-mdq}
132		\lean{MIPStarRE.LDT.Preliminaries.axisLinePolynomialAgreement_avg_eq_scalarDomain, MIPStarRE.LDT.Preliminaries.axisLinePolynomialAgreement_avg_le_mdq}
133		\leanok
134		Let $f,h : \mathrm{AxisLinePolynomial}\,\mathrm{params}$ be two line-polynomial outcomes with distinct underlying polynomials. Then
135		\[
136			\E_{t \sim \F_q}\bigl[\mathbf{1}[f(t)=h(t)]\bigr] \le \frac{md}{q}.
137		\]
138		The native univariate root-counting bound is $d/q$; the statement deliberately pads this to the paper's ambient $md/q$ loss for Lemma~\ref{lem:generalize-b}.
139	\end{lemma}
140	\begin{proof}
141		\leanok
142		Reindex coded line parameters to the scalar field, count the roots of the nonzero univariate polynomial $f-h$, and use $m\ge 1$ to pad $d/q$ to $md/q$.
143	\end{proof}
