/ch11_qpbt_algebra.tex:442:\\begin{definition}[Lines]\\label{def:line}\nblueprint/src/chapter/ch11_qpbt_algebra.tex:458:\\begin{proposition}\\label{prop:line-equiv}\nblueprint/src/chapter/ch11_qpbt_algebra.tex:459:\t\\uses{def:line}\nblueprint/src/chapter/ch11_qpbt_algebra.tex:464:\t\\uses{def:line}\nblueprint/src/chapter/ch11_qpbt_algebra.tex:475:\\begin{definition}[Canonical representative of a line]\\label{def:line-representative}\nblueprint/src/chapter/ch11_qpbt_algebra.tex:476:\t\\uses{def:line, def:cl-canonical, prop:line-equiv}\nblueprint/src/chapter/ch11_qpbt_algebra.tex:501:\\begin{definition}[State space of a linear register]\\label{def:lin-reg}\nblueprint/src/chapter/ch11_qpbt_algebra.tex:502:\t\\uses{def:complementary}\nblueprint/src/chapter/ch11_qpbt_algebra.tex:516:\\begin{definition}[EPR state]\\label{def:EPR}\nblueprint/src/chapter/ch11_qpbt_algebra.tex:517:\t\\uses{def:lin-reg}\nblueprint/src/chapter/ch11_qpbt_algebra.tex:532:\\begin{definition}[Generalized Pauli observables]\\label{def:generalized-pauli}\nblueprint/src/chapter/ch11_qpbt_algebra.tex:533:\t\\uses{def:subfield-trace, def:lin-reg}\nblueprint/src/chapter/ch11_qpbt_algebra.tex:576:\\begin{lemma}[Product and twisted commutation relations]\\label{lem:twisted-commutation}\nblueprint/src/chapter/ch11_qpbt_algebra.tex:577:\t\\uses{def:generalized-pauli, def:subfield-trace, def:dot-product-orthogonal}\nblueprint/src/chapter/ch11_qpbt_algebra.tex:605:\t\\uses{def:generalized-pauli, def:subfield-trace}\nblueprint/src/chapter/ch11_qpbt_algebra.tex:619:\\begin{lemma}[Fourier cancellation over a subspace]\\label{lem:cancellation}\nblueprint/src/chapter/ch11_qpbt_algebra.tex:620:\t\\uses{def:dot-product-orthogonal, def:subfield-trace}\nblueprint/src/chapter/ch11_qpbt_algebra.tex:641:\\begin{lemma}[Fourier expansion of Pauli observables]\\label{lem:pauli-observable-expansion}\nblueprint/src/chapter/ch11_qpbt_algebra.tex:642:\t\\uses{def:generalized-pauli, def:subfield-trace}\nblueprint/src/chapter/ch